import React from "react";
import { motion } from "framer-motion";
import { COLLECTIONS } from "./Content";
import { ArrowRight } from "lucide-react";

export default function Collections() {
  return (
    <section id="collections" className="section" style={{ background: "white" }}>
      <div className="container mx-auto">
        <motion.div className="mb-12 lg:mb-16 text-center" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ duration: 0.6 }}>
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="section-overline">Our Products</span>
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
          </div>
          <h2 className="section-title">Shop by <span>Category</span></h2>
        </motion.div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {COLLECTIONS.map((collection, i) => (
            <motion.div key={collection.id} className="group relative overflow-hidden rounded-2xl aspect-[4/5] cursor-pointer" initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: i * 0.1, duration: 0.5 }} whileHover={{ y: -8 }}>
              <img src={collection.image} alt={collection.title} className="absolute inset-0 w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent" />
              <div className="absolute inset-0 flex flex-col justify-end p-6">
                <span className="text-xs font-medium uppercase tracking-wider mb-2" style={{ color: "#d4af37" }}>{collection.overline}</span>
                <h3 className="serif text-xl font-bold text-white mb-2">{collection.title}</h3>
                <p className="text-sm text-white/70 mb-4 line-clamp-2">{collection.desc}</p>
                <div className="flex items-center gap-2 text-sm font-medium opacity-0 transform translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300" style={{ color: "#d4af37" }}>
                  <span>View Details</span><ArrowRight size={16} />
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
